const data = $input.first().json;

if (data.is_stale) {
  return [{ json: { skip: true, reason: 'signals stale' } }];
}

const signals = data.signals || [];

// Top 3 highest confidence non-FLAT signals
const top = signals
  .filter(s => s.direction !== 'FLAT' && s.confidence >= 0.65)
  .slice(0, 3);

if (top.length === 0) {
  return [{ json: { skip: true, reason: 'no high-confidence signals' } }];
}

const dirEmoji = { LONG: '🟢', SHORT: '🔴' };
const confLabel = c => c >= 0.85 ? 'Very High' : c >= 0.75 ? 'High' : c >= 0.65 ? 'Moderate' : 'Low';

const lines = top.map(s =>
  `${dirEmoji[s.direction]} ${s.symbol} — ${s.direction} | Conf: ${confLabel(s.confidence)} (${Math.round(s.confidence * 100)}%) | ${s.regime}`
);

const generatedAt = data.generated_at
  ? new Date(data.generated_at).toUTCString().replace(':00 GMT', ' UTC')
  : 'now';

const tweet = [
  `⚡ Alpha Alerts — ${new Date().toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })}`,
  '',
  ...lines,
  '',
  `Signals updated: ${generatedAt}`,
  'Full dashboard 👉 https://alphaforgeai.io/signals',
  '',
  '#Crypto #Bitcoin #Ethereum #AlphaForgeAI #AlphaAlerts #CryptoSignals #Trading'
].join('\n');

return [{ json: { tweet, signal_count: top.length, skip: false } }];
